function bulbSwitch(n) {
  // Bulb k is flipped once per divisor of k, so it ends on exactly when k is a perfect square.
  // The answer is how many of 1, 4, 9, 16, ... are at most n, which is floor(sqrt(n)).
  let root = Math.floor(Math.sqrt(n));
  // Correct any floating-point rounding so that root * root <= n < (root + 1) * (root + 1).
  while (root * root > n) {
    root--;
  }
  while ((root + 1) * (root + 1) <= n) {
    root++;
  }
  return root;
}

