function bulbSwitch(n) {
  if (n <= 100000) {
    // Play every round on a real row of bulbs.
    const on = new Uint8Array(n + 1);
    for (let round = 1; round <= n; round++) {
      for (let bulb = round; bulb <= n; bulb += round) on[bulb] ^= 1;
    }
    let count = 0;
    for (let bulb = 1; bulb <= n; bulb++) count += on[bulb];
    return count;
  }
  // Too many bulbs to simulate: list the perfect squares one by one instead.
  let count = 0;
  for (let k = 1; k * k <= n; k++) count++;
  return count;
}

